function calcularEscala(atual, delta) {
    let nova;
    nova = ((atual + delta) | 0);
    if ((nova > 32)) {
        return 32;
    } else {
        if ((nova < 12)) {
            return 12;
        } else {
            return nova;
        }
    }
}

function nomeDoPastoPorId(id) {
    let i;
    if (((id === "") ? 1 : 0)) {
        return "Sem pasto";
    } else {
        i = 0;
        while ((i < kofListSize(UiState.pastoIds))) {
            if (((kofListGet(UiState.pastoIds, i) === id) ? 1 : 0)) {
                return kofListGet(UiState.pastoNomes, i);
            } else {
                i = ((i + 1) | 0);
            }
        }
        return id;
    }
}

